for fn,ops in OPS.items():
    p=root/fn; assert sha(p)==BASE_HASH[fn],(fn,'unexpected predecessor',sha(p),BASE_HASH[fn])
    lines=p.read_bytes().decode('utf-8-sig').splitlines(keepends=True)
    out=[]; pos=0
    for i1,i2,new in ops:
        out.extend(lines[pos:i1]); out.append(new); pos=i2
    out.extend(lines[pos:])
    p.write_text(''.join(out),encoding='utf-8')
for fn,(upd,removed) in JSON_UPDATES.items():
    p=root/fn; assert sha(p)==JSON_BASE_HASH[fn],(fn,'unexpected predecessor',sha(p),JSON_BASE_HASH[fn])
    d=json.loads(p.read_text(encoding='utf-8-sig'))
    for k in removed: d.pop(k,None)
    for k,v in upd.items(): d[k]=v
    p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
for fn,h in EXPECTED.items():
    got=sha(root/fn); assert got==h,(fn,got,h)
